import { S3Client, CreateBucketCommand, DeleteBucketCommand, ListBucketsCommand, ListObjectsV2Command, DeleteObjectsCommand } from "@aws-sdk/client-s3";

const BUCKET = "archive-bucket";
const FORK = "validation-fork";

const s3 = new S3Client({
  region: "auto",
  endpoint: process.env.TIGRIS_STORAGE_ENDPOINT || "https://t3.storage.dev",
  credentials: {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY,
  },
});

async function emptyAndDeleteBucket(bucketName) {
    try {
        const { Contents } = await s3.send(new ListObjectsV2Command({ Bucket: bucketName }));
        if (Contents && Contents.length > 0) {
            await s3.send(new DeleteObjectsCommand({
                Bucket: bucketName,
                Delete: { Objects: Contents.map(c => ({ Key: c.Key })) }
            }));
        }
        await s3.send(new DeleteBucketCommand({ Bucket: bucketName }));
        console.log(`Deleted bucket ${bucketName}`);
    } catch (e) {
        if (e.name !== 'NoSuchBucket') {
            console.warn(`Failed to delete ${bucketName}: ${e.message}`);
        }
    }
}

async function cleanup() {
  const { Buckets } = await s3.send(new ListBucketsCommand({}));
  const toDelete = Buckets?.filter(b => b.Name === BUCKET || b.Name?.startsWith(FORK)) || [];
  for (const b of toDelete) {
    await emptyAndDeleteBucket(b.Name);
  }
}

await cleanup();
console.log(`Creating bucket ${BUCKET}...`);
await s3.send(new CreateBucketCommand({ 
    Bucket: BUCKET,
    ObjectLockEnabledForBucket: true
}));

