  const toDelete = Buckets?.filter(b => b.Name === BUCKET || b.Name?.startsWith(FORK)) || [];
  for (const b of toDelete) {
    await emptyAndDeleteBucket(b.Name);
  }
}

async function createWithRetry(bucketName) {
    for (let i = 0; i < 5; i++) {
        try {
            await s3.send(new CreateBucketCommand({ 
                Bucket: bucketName,
                ObjectLockEnabledForBucket: true
            }));
            console.log(`Created bucket ${bucketName}`);
            return;
        } catch (e) {
            if (e.name === 'BucketInaccessible' || e.name === 'BucketAlreadyExists') {
                console.log(`Bucket ${bucketName} still being processed, retrying in 2s...`);
                await new Promise(r => setTimeout(r, 2000));
            } else {
                throw e;
            }
        }
    }
    throw new Error(`Failed to create bucket ${bucketName} after retries`);
}

await cleanup();
await createWithRetry(BUCKET);

