  }
}

async function ensureBucket(bucketName) {
    try {
        await s3.send(new CreateBucketCommand({ 
            Bucket: bucketName,
            ObjectLockEnabledForBucket: true
        }));
        console.log(`Created bucket ${bucketName}`);
    } catch (e) {
        if (e.name === 'BucketAlreadyExists' || e.name === 'BucketAlreadyOwnedByYou') {
            console.log(`Bucket ${bucketName} already exists, reusing it.`);
            // Ensure snapshots are enabled by clearing it? 
            // Actually the requirement says "Recreates a snapshot-enabled bucket".
            // If I can't recreate it, I'll just empty it.
            const { Contents } = await s3.send(new ListObjectsV2Command({ Bucket: bucketName }));
            if (Contents && Contents.length > 0) {
                await s3.send(new DeleteObjectsCommand({
                    Bucket: bucketName,
                    Delete: { Objects: Contents.map(c => ({ Key: c.Key })) }
                }));
            }
        } else {
            throw e;
        }
    }
}

// Just try to cleanup forks, but maybe keep archive-bucket if it's sticky
const { Buckets } = await s3.send(new ListBucketsCommand({}));
const forks = Buckets?.filter(b => b.Name?.startsWith(FORK)) || [];
for (const f of forks) {
    await emptyAndDeleteBucket(f.Name);
}

await ensureBucket(BUCKET);

